  "uppgifter": [
    {
      "del": null,
      "formaga": "PL",
      "typ": "problem",
      "poang": [0, 0, 0],
      "text": "Gruppen får veta att en andragradsfunktion $f$ har nollställena $x = -1$ och $x = 5$, men inget mer. Undersök tillsammans vilka funktioner som kan passa. Fullständiga lösningar krävs.",
      "innehall": ["nollställen", "faktorform", "symmetrilinje", "extremvärde"],
      "notis": "Fördela talutrymmet: alla tre i gruppen ska kunna förklara minst en av deluppgifterna vid redovisningen.",
      "deluppgifter": [
        {
          "formaga": "B",
          "typ": "resonemang",
          "poang": [1, 0, 0],
          "text": "Förklara varför varje sådan funktion kan skrivas $f(x) = a(x + 1)(x - 5)$ där $a \\neq 0$, och ge tre olika exempel.",
          "losning": "Nollställena ger faktorerna $(x + 1)$ och $(x - 5)$. Alla andragradsfunktioner med just dessa nollställen är en konstant $a \\neq 0$ gånger produkten, t.ex. $a = 1$, $a = 2$ och $a = -3$.",
          "bedomning": "+1 E för korrekt faktorform med förklaring och minst två giltiga exempel."
        },
        {
          "formaga": "P",
          "typ": "redovisning",
          "poang": [1, 1, 0],
          "text": "En av funktionerna går genom punkten $(1, -12)$. Bestäm funktionen på formen $f(x) = ax^2 + bx + c$ och funktionens minsta värde.",
          "losning": "$f(1) = a(2)(-4) = -8a = -12$ ger $a = 1{,}5$. Alltså $f(x) = 1{,}5(x+1)(x-5) = 1{,}5x^2 - 6x - 7{,}5$. Symmetrilinjen är $x = 2$ och $f(2) = 1{,}5 \\cdot 4 - 12 - 7{,}5 = -13{,}5$.",
          "bedomning": "+1 E korrekt bestämt $a$ och funktionsuttryck, +1 C korrekt minsta värde med redovisad symmetrilinje."
        },
        {
          "formaga": "PL",
          "typ": "problem",
          "poang": [0, 1, 1],
          "text": "Diskutera i gruppen: går det att välja $a$ så att funktionens minsta värde blir $-3$? Går det att välja $a$ så att funktionen får största värdet $12$? Motivera ditt svar.",
          "losning": "Symmetrilinjen är alltid $x = 2$ och $f(2) = a(3)(-3) = -9a$. Minsta värde kräver $a > 0$: $-9a = -3$ ger $a = \\tfrac{1}{3} > 0$, alltså möjligt. Största värde kräver $a < 0$: $-9a = 12$ ger $a = -\\tfrac{4}{3} < 0$, alltså möjligt. Båda går, men bara för ett enda $a$ i varje fall.",
          "bedomning": "+1 C ansats där extremvärdet uttrycks som $-9a$ och ett av fallen avgörs, +1 A båda fallen avgjorda med motivering av teckenkravet på $a$."
        }
      ]
    },
    {
      "del": null,
      "formaga": "M",
      "typ": "problem",
      "poang": [0, 0, 0],
      "text": "En elevförening säljer biljetter till en föreställning. Vid ett provsläpp noterades hur många biljetter som såldes vid olika priser enligt tabellen. Använd tabellen som underlag för en modell över föreningens intäkt.",
      "innehall": ["matematisk modell", "intäktsfunktion", "maximum", "modellens giltighet"],
      "tabell": {
        "rubriker": ["Biljettpris (kr)", "Antal sålda biljetter"],
        "rader": [
          ["50", "240"],
          ["60", "200"],
          ["70", "160"],
          ["80", "120"]
        ]
      },
      "deluppgifter": [
        {
          "formaga": "M",
          "typ": "redovisning",
          "poang": [1, 1, 0],
          "text": "Visa med hjälp av tabellen att antalet sålda biljetter kan beskrivas av en linjär funktion av priset $p$, och teckna sedan en modell $I(p)$ för intäkten.",
          "losning": "Antalet minskar med $4$ biljetter per krona: $N(p) = 440 - 4p$ (kontroll: $N(50) = 240$). Intäkten blir $I(p) = p(440 - 4p) = 440p - 4p^2$.",
          "bedomning": "+1 E korrekt linjär modell för antalet, +1 C korrekt tecknad intäktsfunktion."
        },
        {
          "formaga": "PL",
          "typ": "problem",
          "poang": [1, 1, 0],
          "text": "Bestäm det biljettpris som ger störst intäkt och hur stor intäkten då blir.",
          "enhet": "kr",
          "losning": "$I(p) = -4p^2 + 440p$ har nollställena $p = 0$ och $p = 110$, alltså symmetrilinjen $p = 55$. $I(55) = 55 \\cdot 220 = 12100$. Störst intäkt $12\\,100$ kr vid priset $55$ kr.",
          "bedomning": "+1 E ansats med symmetrilinje eller nollställen, +1 C korrekt pris och intäkt med redovisning."
        },
        {
          "formaga": "R",
          "typ": "resonemang",
          "poang": [0, 0, 1],
          "text": "Diskutera i gruppen vad modellen ger för priserna $0$ kr och $120$ kr och bedöm för vilka priser modellen är rimlig att använda. Motivera ditt svar.",
          "losning": "Vid $p = 0$ ger modellen $N = 440$ besökare och intäkten $0$ kr, vilket kan vara orimligt om lokalen är mindre än så. Vid $p = 120$ ger modellen $N = -40$, ett negativt antal, vilket är omöjligt. Modellen är rimlig ungefär för $0 \\le p \\le 110$ och dessutom bara i närheten av de uppmätta priserna, eftersom antagandet om linjär minskning är en förenkling.",
          "bedomning": "+1 A resonemang som både påvisar det negativa antalet och drar en välmotiverad slutsats om giltighetsområdet."
        }
      ]
    },
    {
      "del": null,
      "formaga": "R",
      "typ": "resonemang",
      "poang": [1, 1, 1],
      "text": "Kim ska bestämma det minsta värdet för $f(x) = x^2 - 8x + 11$ med kvadratkomplettering. Läs Kims lösning tillsammans och kryssa i det första steget som är felaktigt. Förklara sedan vad felet består i och bestäm det korrekta minsta värdet. Fullständiga lösningar krävs.",
      "innehall": ["kvadratkomplettering", "minsta värde", "felanalys"],
      "stegtabell": {
        "kolumner": ["Kims lösning"],
        "steg": [
          { "celler": ["$f(x) = x^2 - 8x + 11$"] },
          { "celler": ["$f(x) = (x - 4)^2 + 11$"] },
          { "celler": ["$(x - 4)^2 \\ge 0$ för alla $x$"] },
          { "celler": ["Minsta värdet är $11$ och det fås då $x = 4$"] }
        ],
        "forsta_fel": 1
      },
      "losning": "Steg 2 är fel: $(x-4)^2 = x^2 - 8x + 16$, så man måste dra bort $16$. Korrekt är $f(x) = (x-4)^2 - 16 + 11 = (x-4)^2 - 5$. Eftersom $(x-4)^2 \\ge 0$ blir minsta värdet $-5$, vilket fås då $x = 4$.",
      "bedomning": "+1 E korrekt markerat första felaktiga steg, +1 C förklaring av felet med korrekt kvadratkomplettering, +1 A korrekt minsta värde med motivering utifrån att kvadraten aldrig är negativ.",
      "elevlosningar": [
        {
          "etikett": "Elevlösning 1",
          "partier": [
            {
              "rader": ["Steg 3 är fel.", "Minsta värdet är $-11$."],
              "poang": [0, 0, 0],
              "dom": "Fel steg markerat och svaret $-11$ saknar både uträkning och koppling till kvadratkompletteringen. Ingen poäng."
            }
          ]
        },
        {
          "etikett": "Elevlösning 2",
          "partier": [
            {
              "rader": ["Steg 2 är fel.", "$(x-4)^2$ blir $x^2 - 8x + 16$, inte $x^2 - 8x$."],
              "poang": [1, 0, 0],
              "dom": "Rätt steg markerat och antydan till förklaring. Ger E-poängen."
            },
            {
              "rader": ["Alltså ska det stå $(x-4)^2 + 16 + 11$.", "Minsta värdet är $27$."],
              "poang": [0, 0, 0],
              "dom": "Kvadratkompletteringen görs med fel tecken, så varken C- eller A-poängen kan ges."
            }
          ]
        },
        {
          "etikett": "Elevlösning 3",
          "partier": [
            {
              "rader": ["Steg 2 är fel."],
